class Solution {
public:
    vector<int> goodSubsetofBinaryMatrix(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        unordered_map<int, int> first_occ;
        for (int r = 0; r < m; ++r) {
            int mask = 0;
            for (int c = 0; c < n; ++c) {
                if (grid[r][c]) mask |= (1 << c);
            }
            if (mask == 0) return {r};
            if (!first_occ.count(mask)) first_occ[mask] = r;
        }
        for (auto& [m1, r1] : first_occ) {
            for (auto& [m2, r2] : first_occ) {
                if ((m1 & m2) == 0) {
                    if (r1 < r2) return {r1, r2};
                    else return {r2, r1};
                }
            }
        }
        return {};
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public java.util.List<Integer> goodSubsetofBinaryMatrix(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Map<Integer, Integer> firstOcc = new HashMap<>();
        for (int r = 0; r < m; r++) {
            int mask = 0;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) mask |= (1 << c);
            }
            if (mask == 0) return java.util.List.of(r);
            firstOcc.putIfAbsent(mask, r);
        }
        for (var e1 : firstOcc.entrySet()) {
            for (var e2 : firstOcc.entrySet()) {
                if ((e1.getKey() & e2.getKey()) == 0) {
                    int r1 = e1.getValue(), r2 = e2.getValue();
                    return r1 < r2 ? java.util.List.of(r1, r2) : java.util.List.of(r2, r1);
                }
            }
        }
        return java.util.List.of();
    }
}

var goodSubsetofBinaryMatrix = function(grid) {
    const m = grid.length, n = grid[0].length;
    const firstOcc = new Map();
    for (let r = 0; r < m; r++) {
        let mask = 0;
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) mask |= (1 << c);
        }
        if (mask === 0) return [r];
        if (!firstOcc.has(mask)) firstOcc.set(mask, r);
    }
    for (const [m1, r1] of firstOcc) {
        for (const [m2, r2] of firstOcc) {
            if ((m1 & m2) === 0) {
                return r1 < r2 ? [r1, r2] : [r2, r1];
            }
        }
    }
    return [];
};
